public class Solution {
    public boolean isValid(String s) {
        // считает только количество, не порядок
        int open = 0, close = 0;
        for (char c : s.toCharArray()) {
            if (c == '(' || c == '[' || c == '{') open++;
            else close++;
        }
        return open == close;
    }
}
